 h=t['id']+' — '+t['title'];body=f\"kind: "'`{t['"'kind']}"'`; status: `{t['"'status']}"'`'"\\nUS refs: {', '.join(t['us_refs'])}\\ndepends_on: {', '.join(t['depends_on']) or 'ไม่มี'}\\n\\nInputs:\\n\\n{bullets(t['inputs'])}\\n\\nOutputs ที่วางแผน ยังไม่ได้สร้าง:\\n\\n{bullets(t['outputs'])}\\n\\nเหตุผลและ dependency ทุกเส้น: {t['reason']}\"
 if sections.get(h)"'!=body:errs.append(h)
for d in p['"'decisions']:
 h=d['id']+' — '+d['topic'];body=f\"authority: "'`{d['"'authority']}"'`'"\\n\\n{d['decision']}\\n\\nหลักฐาน:\\n\\n{bullets(d['evidence'])}\"
 if sections.get(h)"'!=body:errs.append(h)
for r in p['"'reuse']:
 h=Path(r['artifact']).name;body=f\"artifact: "'`{r['"'artifact']}"'`'"\\nsource_version: "'`{r['"'source_version']}"'`'"\\ndisposition: "'`{r['"'disposition']}"'`'"\\n\\n{r['reason']}\\n\\nหลักฐานตรวจเดิม/ที่มา:\\n\\n{bullets(r['evidence'])}\"
 if sections.get(h)"'!=body:errs.append(h)
