 h=l['id'];af=', '.join(l['affected_tasks']) or '[] — ระบบจริงอยู่นอก tasks แผนนี้';body=f\"blocking: "'`{str(l['"'blocking']).lower()}"'`'"\\naffected_tasks: {af}\\n\\n{l['description']}\"
 if sections.get(h)"'!=body:errs.append(h)
